  "new_string": "// ── Auto accent: derive the accent hue from the active background ──
// The accent tracks the background's dominant hue; the theme keeps saturation
// and lightness (see meridian.css), and a contrast guard nudges lightness so
// the accent can never collapse into a same-toned solid background.

function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return null;
  let h = m[1];
  if (h.length === 3) h = h.split("").map((c) => c + c).join("");
  const int = parseInt(h, 16);
  return [(int >> 16) & 255, (int >> 8) & 255, int & 255];
}

function rgbToHsl(r, g, b) {
  r /= 255;
  g /= 255;
  b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  const d = max - min;
  let h = 0;
  let s = 0;
  if (d !== 0) {
    s = d / (1 - Math.abs(2 * l - 1));
    if (max === r) h = ((g - b) / d) % 6;
    else if (max === g) h = (b - r) / d + 2;
    else h = (r - g) / d + 4;
    h = Math.round(h * 60);
    if (h < 0) h += 360;
  }
  return { h, s: Math.round(s * 100), l: Math.round(l * 100) };
}

// Average every hex color in a string (gradients carry several stops).
function averageHexes(str) {
  const hexes = String(str).match(/#[0-9a-f]{6}|#[0-9a-f]{3}/gi);
  if (!hexes || !hexes.length) return null;
  let r = 0;
  let g = 0;
  let b = 0;
  for (const hx of hexes) {
    const c = hexToRgb(hx);
    if (!c) continue;
    r += c[0];
    g += c[1];
    b += c[2];
  }
  return rgbToHsl(r / hexes.length, g / hexes.length, b / hexes.length);
}

// Downsample an image and average its opaque pixels to a dominant color.
function dominantFromImage(url) {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const size = 32;
        const canvas = document.createElement("canvas");
        canvas.width = size;
        canvas.height = size;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, size, size);
        const { data } = ctx.getImageData(0, 0, size, size);
        let r = 0;
        let g = 0;
        let b = 0;
        let n = 0;
        for (let i = 0; i < data.length; i += 4) {
          if (data[i + 3] < 125) continue;
          r += data[i];
          g += data[i + 1];
          b += data[i + 2];
          n += 1;
        }
        resolve(n ? rgbToHsl(r / n, g / n, b / n) : null);
      } catch {
        resolve(null); // cross-origin taint, etc. — fall back to default hue
      }
    };
    img.onerror = () => resolve(null);
    img.src = url;
  });
}

async function dominantForBackground(bg, customDataUrl) {
  if (!bg || bg.type === "none") return null;
  if (bg.type === "solid") {
    const rgb = hexToRgb(bg.value);
    return rgb ? rgbToHsl(...rgb) : null;
  }
  if (bg.type === "gradient") return averageHexes(bg.value);
  if (bg.type === "photo") return dominantFromImage(bg.value);
  if (bg.type === "custom") {
    return customDataUrl ? dominantFromImage(customDataUrl) : null;
  }
  return null;
}

// Last resolved dominant, cached so a theme switch can re-run the guard.
let lastDominant = null;

function docIsDark() {
  const t = document.documentElement.dataset.theme;
  if (t === "dark") return true;
  if (t === "light") return false;
  return window.matchMedia("(prefers-color-scheme: dark)").matches;
}

function applyDerivedAccent(dominant) {
  const root = document.documentElement;
  // Grayscale / very desaturated → no meaningful hue; use the default.
  if (!dominant || dominant.s < 12) {
    root.style.removeProperty("--accent-hue");
    root.style.removeProperty("--accent-light");
    return;
  }
  root.style.setProperty("--accent-hue", String(dominant.h));

  // Contrast guard: if the theme's accent lightness sits too close to the
  // background's, push it away so the accent stays visible against a solid.
  const themeL = docIsDark() ? 52 : 45;
  if (Math.abs(themeL - dominant.l) >= 22) {
    root.style.removeProperty("--accent-light");
  } else {
    const pushed =
      dominant.l < 50
        ? Math.min(dominant.l + 32, 82)
        : Math.max(dominant.l - 32, 24);
    root.style.setProperty("--accent-light", `${pushed}%`);
  }
}

export async function applyAccentFromBackground(bg, customDataUrl = null) {
  const dominant = await dominantForBackground(bg, customDataUrl);
  lastDominant = dominant;
  applyDerivedAccent(dominant);
}

export function applyTheme(theme) {
  const html = document.documentElement;
  if (theme === "light") {
    html.dataset.theme = "light";
  } else if (theme === "dark") {
    html.dataset.theme = "dark";
  } else {
    delete html.dataset.theme;
  }
  // The guard's lightness push depends on the theme — re-run it on switch.
  applyDerivedAccent(lastDominant);
}"
