1	import {
2	  assignTab,
3	  unassignTab,
4	  createWorkspace,
5	  getWorkspaceData,
6	} from "../utils/workspaceManager.js";
7	
8	const hasNativeGroups = typeof chrome.tabGroups !== "undefined";
9	
10	let menuEl = null;
11	
12	function getMenu() {
13	  if (menuEl) return menuEl;
14	  menuEl = document.createElement("div");
15	  menuEl.className = "context-menu hidden";
16	  menuEl.setAttribute("role", "menu");
17	  document.body.appendChild(menuEl);
18	  document.addEventListener("mousedown", (e) => {
19	    if (!menuEl.contains(e.target)) hide();
20	  });
21	  document.addEventListener("keydown", (e) => {
22	    if (e.key === "Escape") hide();
23	  });
24	  return menuEl;
25	}
26	
27	export function hide() {
28	  getMenu().classList.add("hidden");
29	}
30	
31	function item(label, onClick) {
32	  const btn = document.createElement("button");
33	  btn.className = "context-menu-item";
34	  btn.setAttribute("role", "menuitem");
35	  btn.textContent = label;
36	  btn.addEventListener("click", (e) => {
37	    e.stopPropagation();
38	    hide();
39	    onClick();
40	  });
41	  return btn;
42	}
43	
44	function separator() {
45	  const el = document.createElement("div");
46	  el.className = "context-menu-separator";
47	  return el;
48	}
49	
50	export async function show(tab, x, y) {
51	  const menu = getMenu();
52	  menu.innerHTML = "";
53	
54	  const [chromeGroups, wsData] = await Promise.all([
55	    hasNativeGroups ? chrome.tabGroups.query({}) : Promise.resolve([]),
56	    getWorkspaceData(),
57	  ]);
58	
59	  const inChromeGroup = hasNativeGroups && tab.groupId !== -1;
60	  const wsId = wsData.assignments[String(tab.id)];
61	  const customWorkspaces = wsData.workspaces.filter((w) => w.id !== "unsorted");
62	
63	  // Move to new group
64	  menu.appendChild(
65	    item("Move to new group", async () => {
66	      const name = prompt("New group name:");
67	      if (!name?.trim()) return;
68	      if (hasNativeGroups) {
