133	    input.value = "";
134	    updateClearBtn();
135	  }
136	
137	  // Left glyph is a signifier; clicking it just returns focus to the field.
138	  logoBtn.addEventListener("click", (e) => {
139	    e.stopPropagation();
140	    input.focus();
141	  });
142	
143	  input.addEventListener("input", () => {
144	    updateClearBtn();
